<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
const placement=ref('bottom'),hovered=ref(false),focused=ref(false),dismissed=ref(false),trigger=ref<HTMLButtonElement|null>(null),tip=ref<HTMLElement|null>(null),position=ref({left:'0px',top:'0px'}),actual=ref('top')
const ready=ref(false)
const open=computed(()=>ready.value&&!dismissed.value&&(hovered.value||focused.value))
let entry:ReturnType<typeof setTimeout>|undefined
let timer:ReturnType<typeof setTimeout>|undefined
async function locate(){await nextTick();if(!open.value||!trigger.value||!tip.value)return;const a=trigger.value.getBoundingClientRect(),b=tip.value.getBoundingClientRect(),gap=8,pad=12;let side=placement.value;let x=a.left+(a.width-b.width)/2,y=a.top-b.height-gap;if(side==='top'&&y<pad)side='bottom';if(side==='bottom'&&a.bottom+gap+b.height>innerHeight-pad)side='top';if(side==='start'&&a.left-gap-b.width<pad)side='end';if(side==='end'&&a.right+gap+b.width>innerWidth-pad)side='start';if((side==='start'&&a.left-gap-b.width<pad)||(side==='end'&&a.right+gap+b.width>innerWidth-pad))side=a.top-b.height-gap>=pad?'top':'bottom';if(side==='bottom')y=a.bottom+gap;if(side==='start'){x=a.left-b.width-gap;y=a.top+(a.height-b.height)/2}if(side==='end'){x=a.right+gap;y=a.top+(a.height-b.height)/2}actual.value=side;position.value={left:`${Math.max(pad,Math.min(x,innerWidth-b.width-pad))}px`,top:`${Math.max(pad,Math.min(y,innerHeight-b.height-pad))}px`}}
function enter(){clearTimeout(timer);hovered.value=true;entry=setTimeout(()=>{ready.value=true;locate()},300)}
function leave(){clearTimeout(timer);clearTimeout(entry);timer=setTimeout(()=>{hovered.value=false;reset()},180)}
function reset(){if(!hovered.value&&!focused.value){dismissed.value=false;ready.value=false}}
function focus(){clearTimeout(entry);focused.value=true;ready.value=true;locate()}
function blur(){focused.value=false;reset()}
function escape(e:KeyboardEvent){if(e.key==='Escape'&&open.value)dismissed.value=true}
onMounted(()=>{window.addEventListener('keydown',escape);window.addEventListener('resize',locate);window.addEventListener('scroll',locate,true)})
onBeforeUnmount(()=>{clearTimeout(timer);clearTimeout(entry);window.removeEventListener('keydown',escape);window.removeEventListener('resize',locate);window.removeEventListener('scroll',locate,true)})
</script>
<template><section class="hover-card-usage" aria-label="Hover card usage demonstration"><label>Preferred card placement<select v-model="placement" @change="locate"><option>top</option><option>bottom</option><option>start</option><option>end</option></select></label><p>Fictitious local example. The button has no business action. Optional profile context is also available below for touch users.</p><div class="stage"><span class="anchor" @pointerenter="enter" @pointerleave="leave"><button ref="trigger" type="button" :aria-describedby="open?'hover-card-guide-help':undefined" @focus="focus" @blur="blur">Sample person context</button><span v-show="open" id="hover-card-guide-help" ref="tip" role="note" :style="position" :data-placement="actual"><strong>Alex Example</strong><br>Fictitious product designer<br>Sample workspace · No live presence</span></span></div><details><summary>Read sample profile without hover</summary><p><strong>Alex Example</strong><br>Fictitious product designer<br>Sample workspace · No live presence</p></details></section></template>
